// 同原六角报价/resolve检验四档实际伤害和人数；不替代入战历史、Common伤亡结算或World银行。
#include "resident/domains/military/military_combat_conditions.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0;void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}template<class T>T take(Outcome<T> r){if(!r.ok)throw std::runtime_error(r.error.original.code+":"+r.error.original.path);return std::move(r.value);}void good(Status s){if(!s.ok)throw std::runtime_error(s.error.original.code);}
MilitaryBattleCatalog catalog(){MilitaryBattleCatalog c;c.rout_retreat_enabled=true;c.combat_condition_rule=MilitaryCombatConditionRule{};BattlefieldDefinition board;board.id="field";board.objective_id="goal";board.rout_retreat=MilitaryRoutRetreatRule{};board.damage_model.kind="legacy_base_factors_v1";board.damage_model.present=true;board.damage_model.empty=false;for(Integer q=0;q<3;++q){HexCell cell;cell.q=q;cell.terrain="plain";board.cells.push_back(cell);}board.spawns={{0,{0,0},{}},{1,{2,0},{}}};board.exits=board.spawns;c.battlefields={board};BattleObjectiveDefinition goal;goal.id="goal";goal.kind="repel";goal.max_rounds=10;c.objectives={goal};TroopDefinition t;t.id="foot";t.category="infantry";t.movement=1;t.attack=100;t.accuracy=100;t.movement_costs={{"plain",1},{"forest",1},{"hill",1},{"water",0},{"wall",0}};c.troop_types={t};return c;}
MilitaryBattleRecord frame(Integer fatigue){MilitaryBattleRecord b;b.id="battle:1";b.battlefield_id="field";b.objective_id="goal";b.rout_retreat_enabled=true;b.controller_actor_id="captain";b.command_scope="unit";b.command_unit_ids={"unit"};BattleUnit u;u.unit_id="unit";u.army_id="army:1";u.commander_actor_id="captain";u.troop_type_id="foot";u.morale=100;for(Integer i=0;i<100;++i)u.fit.push_back("u"+std::to_string(i));u.member_ids=u.fit;BattleUnit e=u;e.unit_id="enemy";e.army_id="army:2";e.commander_actor_id="other";e.side=1;e.position={1,0};e.heading=3;e.fit.clear();for(Integer i=0;i<100;++i)e.fit.push_back("e"+std::to_string(i));e.member_ids=e.fit;b.units={u,e};b.ai_plans={{"enemy",{"wait",e.position,e.heading,{},{},{}}}};MilitaryCombatConditionState state;state.units={{"enemy","camp",{},Integer(20),Integer(0),10000,{}},{"unit","camp","military:4",Integer(20),fatigue,take(military_combat_fatigue_efficiency(fatigue)),{}}};b.combat_conditions=std::move(state);return b;}
}
int main(){try{auto cat=catalog();for(const auto& row:{std::pair<Integer,Integer>{0,10000},{39,10000},{40,9000},{69,9000},{70,7500},{89,7500},{90,6000},{100,6000}}){check(take(military_combat_fatigue_efficiency(row.first))==row.second,"exact original fatigue band");auto b=frame(row.first);good(validate_military_battle(b,cat,true));MilitaryOrder command;command.action="attack";command.destination=b.units[0].position;command.target_id="enemy";auto quote=take(preview_military_order(b,cat,"unit",command));check(quote.casualties_min==row.second/100&&quote.casualties_max==row.second/100,"same real attack quote uses frozen band once");Integer draws=0;MilitaryBattleRandom random=[&](StableId&,StableId&,Integer from,Integer to)->Outcome<Integer>{++draws;check(from==1&&to==100,"original random range unchanged");return {true,100,{}};};auto after=take(resolve_military_round(b,cat,"captain",{{"unit",command}},random));check(draws==1,"original one attack draws once");const auto& target=after.units[1];check(target.fit.size()+target.wounded.size()+target.dead.size()+target.captured.size()+target.deserted.size()==100&&target.wounded.size()+target.dead.size()==std::size_t(row.second/100),"real round exact casualties and conserved original people");check(after.combat_conditions->units[1].fatigue==b.combat_conditions->units[1].fatigue,"round does not rewrite frozen unit condition");}
 check(!military_combat_fatigue_efficiency(-1).ok&&!military_combat_fatigue_efficiency(101).ok,"out of range fatigue rejected");auto b=frame(70);b.combat_conditions->units[1].efficiency_bp=10000;check(!validate_military_battle(b,cat).ok,"forged favorable efficiency rejected");b=frame(70);b.combat_conditions->units.erase(b.combat_conditions->units.begin());check(!validate_military_battle(b,cat).ok,"missing row never defaults neutral");b=frame(70);b.combat_conditions->units[1].training.reset();check(!validate_military_battle(b,cat).ok,"partial original profile rejected");b=frame(70);b.combat_conditions->units[1].training.reset();b.combat_conditions->units[1].fatigue.reset();b.combat_conditions->units[1].last_condition_fact_id.clear();b.combat_conditions->units[1].efficiency_bp=10000;good(validate_military_battle(b,cat));check(take(military_combat_attack_efficiency(b,"unit"))==10000,"unconfigured source is explicit neutral");auto old=frame(0);old.rout_retreat_enabled=false;old.combat_conditions.reset();auto old_catalog=cat;old_catalog.combat_condition_rule.reset();MilitaryOrder attack;attack.action="attack";attack.target_id="enemy";auto legacy=take(preview_military_order(old,old_catalog,"unit",attack)),loaded=take(preview_military_order(old,cat,"unit",attack));check(legacy.casualties_min==loaded.casualties_min&&legacy.casualties_max==loaded.casualties_max,"unselected old session unchanged by loaded new rule");
 std::cout<<"MILITARY_COMBAT_CONDITIONS="<<checks<<" FAILURES=0 SCOPE=ORIGINAL_ROUND_COMPONENT\n";return 0;}catch(const std::exception& e){std::cerr<<"MILITARY_COMBAT_CONDITIONS_FAIL "<<checks<<" "<<e.what()<<'\n';return 1;}}
